create extension if not exists pgcrypto;
create table if not exists companies(id uuid primary key default gen_random_uuid(),ticker text not null unique,cik text,company_name_en text not null,vertical text not null,exchange text not null,description text,priority_tier int not null default 3,profile_completeness_score int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists company_market_profiles(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),market_code text not null,language_code text not null,company_aliases_json jsonb not null default '[]',products_games_apps_brands_json jsonb not null default '[]',competitor_aliases_json jsonb not null default '[]',event_terms_json jsonb not null default '{}',ambiguity_notes jsonb not null default '[]',source_preferences_json jsonb not null default '[]',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,market_code,language_code));
create table if not exists company_import_runs(id uuid primary key default gen_random_uuid(),source_file_name text not null,imported_at timestamptz not null default now(),imported_by text,total_profiles int not null default 0,created_profiles int not null default 0,updated_profiles int not null default 0,rejected_profiles int not null default 0,warnings_json jsonb not null default '[]',errors_json jsonb not null default '[]',status text not null);
create table if not exists source_documents(id uuid primary key default gen_random_uuid(),company_id uuid references companies(id),market_code text,source_type text not null,source_name text,source_domain text,language_code text,country_code text,title_original text,excerpt_original text,source_url text,canonical_url text,published_at timestamptz,discovered_at timestamptz not null default now(),source_quality_tier int,entity_match_confidence numeric,content_hash text,raw_metadata_json jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists document_analyses(id uuid primary key default gen_random_uuid(),document_id uuid not null references source_documents(id),title_en text,excerpt_en text,translation_status text,event_category text,topic_tags_json jsonb,fundamental_driver_tags_json jsonb,evidence_excerpts_json jsonb,uncertainty_flags_json jsonb,analysis_confidence numeric,analysis_version text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists candidate_events(id uuid primary key default gen_random_uuid(),company_id uuid references companies(id),market_code text,event_category text,topic text,status text not null,detected_at timestamptz,last_updated_at timestamptz,query_budget_tier text,candidate_score numeric,reason_json jsonb,entity_match_confidence numeric,freshness_score numeric,source_count int,independent_source_count int,is_active_investigation boolean default false,expiry_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists research_leads(id uuid primary key default gen_random_uuid(),company_id uuid references companies(id),market_code text,event_category text,topic text,status text,time_window text,direction text,first_detected_at timestamptz,last_updated_at timestamptz,event_age_hours numeric,recency_score numeric,source_quality_score numeric,local_source_concentration_score numeric,english_coverage_gap_score numeric,ambiguity_or_duplicate_penalty numeric,research_priority_score numeric,evidence_level text,entity_match_confidence numeric,independent_source_count int,fundamental_driver_tags_json jsonb,research_observation text,research_starting_question text,potential_business_relevance text,alternative_explanations_json jsonb,validation_steps_json jsonb,verified_evidence_json jsonb,english_sample_definition_json jsonb,methodology_version text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists research_lead_documents(research_lead_id uuid references research_leads(id),document_id uuid references source_documents(id),relationship_type text,created_at timestamptz default now(),primary key(research_lead_id,document_id));
create table if not exists connector_runs(id uuid primary key default gen_random_uuid(),connector_name text,job_name text,company_id uuid,market_code text,status text,started_at timestamptz,completed_at timestamptz,cursor_before_json jsonb,cursor_after_json jsonb,items_fetched int default 0,items_deduplicated int default 0,items_stored int default 0,api_requests_used int default 0,query_cost_estimate numeric,error_message text,metadata_json jsonb,created_at timestamptz default now());
create table if not exists source_query_cache(id uuid primary key default gen_random_uuid(),connector_name text,company_id uuid,market_code text,normalized_query text,request_fingerprint text,response_hash text,fetched_at timestamptz,expires_at timestamptz,metadata_json jsonb);
create table if not exists query_budgets(id uuid primary key default gen_random_uuid(),connector_name text,budget_period text,max_requests int,used_requests int default 0,reserved_requests int default 0,last_reset_at timestamptz,updated_at timestamptz default now(),unique(connector_name,budget_period));
create table if not exists watchlists(id uuid primary key default gen_random_uuid(),name text,description text,is_public boolean default false,created_at timestamptz default now());
create table if not exists watchlist_companies(watchlist_id uuid references watchlists(id),company_id uuid references companies(id),created_at timestamptz default now(),primary key(watchlist_id,company_id));
create index if not exists source_documents_company_idx on source_documents(company_id); create index if not exists source_documents_published_idx on source_documents(published_at); create index if not exists candidate_status_idx on candidate_events(status); create index if not exists leads_priority_idx on research_leads(research_priority_score desc);
alter table companies enable row level security; alter table company_market_profiles enable row level security; alter table source_documents enable row level security; alter table candidate_events enable row level security; alter table research_leads enable row level security;
create policy "public read companies" on companies for select using (is_active=true); create policy "public read markets" on company_market_profiles for select using (enabled=true); create policy "public read documents" on source_documents for select using (true); create policy "public read candidates" on candidate_events for select using (true); create policy "public read leads" on research_leads for select using (true);
